namespace NetEvolve.Pulse.Tests.Unit.EntityFramework;

using System;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.Extensions.Options;
using NetEvolve.Extensions.TUnit;
using NetEvolve.Pulse.Configurations;
using NetEvolve.Pulse.Extensibility.Outbox;
using NetEvolve.Pulse.Outbox;
using TUnit.Core;

/// <summary>
/// Tests the 63-character identifier limit handling (PostgreSQL) of the primary key and index names
/// generated by <see cref="OutboxMessageConfigurationBase"/>.
/// </summary>
[TestGroup("EntityFramework")]
public sealed class OutboxMessageConfigurationIdentifierTruncationTests
{
    private const int MaxIdentifierLength = 63;

    // "PK_pulse_" is 9 characters, so a 54-character table name yields a primary key name of exactly 63 characters.
    private static readonly string ExactFitTableName = new('A', 54);

    // One character more and the name no longer fits, so it is shortened and gets a hash suffix.
    private static readonly string TooLongTableName = new('A', 55);

    private static IMutableEntityType GetEntityType(string tableName)
    {
        var modelBuilder = new ModelBuilder();
        var configuration = new PostgreSqlOutboxMessageConfiguration(
            Options.Create(new OutboxOptions { TableName = tableName })
        );

        _ = modelBuilder.ApplyConfiguration(configuration);
        return modelBuilder.Model.FindEntityType(typeof(OutboxMessage))!;
    }

    [Test]
    public async Task Configure_WithNameExactlyAtLimit_KeepsPrimaryKeyNameUnchanged()
    {
        var entityType = GetEntityType(ExactFitTableName);

        var name = entityType.FindPrimaryKey()!.GetName();

        using (Assert.Multiple())
        {
            _ = await Assert.That(name).IsEqualTo($"PK_pulse_{ExactFitTableName}");
            _ = await Assert.That(name!.Length).IsEqualTo(MaxIdentifierLength);
        }
    }

    [Test]
    public async Task Configure_WithNameExceedingLimit_TruncatesPrimaryKeyNameWithStableHashSuffix()
    {
        var entityType = GetEntityType(TooLongTableName);

        var name = entityType.FindPrimaryKey()!.GetName();

        // The suffix is the 32-bit FNV-1a hash of the full, untruncated name. Changing it would rename
        // existing constraints and indexes, so the value is pinned here.
        using (Assert.Multiple())
        {
            _ = await Assert.That(name).IsEqualTo($"PK_pulse_{new string('A', 45)}_70699d64");
            _ = await Assert.That(name!.Length).IsEqualTo(MaxIdentifierLength);
        }
    }

    [Test]
    public async Task Configure_WithNameExceedingLimit_TruncatesIndexNamesAndKeepsThemDistinct()
    {
        var entityType = GetEntityType(TooLongTableName);

        var names = entityType.GetIndexes().Select(index => index.GetDatabaseName()!).ToArray();

        using (Assert.Multiple())
        {
            _ = await Assert.That(names.All(n => n.Length == MaxIdentifierLength)).IsTrue();
            _ = await Assert.That(names.Distinct(StringComparer.Ordinal).Count()).IsEqualTo(3);
            _ = await Assert
                .That(names)
                .Contains($"IX_pulse_{new string('A', 45)}_74116921")
                .And.Contains($"IX_pulse_{new string('A', 45)}_e8d1c034")
                .And.Contains($"IX_pulse_{new string('A', 45)}_3f560a7d");
        }
    }
}
